import subprocess, re, json
from html.parser import HTMLParser

def fetch_wiki(url):
    result = subprocess.run(['curl', '-s', '-L', '-H', 
        'User-Agent: Mozilla/5.0 (X11; Linux x86_64; rv:109.0) Gecko/20100101 Firefox/115.0',
        '-H', 'Accept: text/html', url], capture_output=True, text=True, timeout=30)
    return result.stdout

class WikiTableParser(HTMLParser):
    """Parse wikitables handling rowspan/colspan"""
    def __init__(self):
        super().__init__()
        self.tables = []
        self.in_wikitable = 0  # depth
        self.in_row = False
        self.in_cell = False
        self.current_table_raw = []  # list of rows, each row = list of (text, rowspan, colspan)
        self.current_row = []
        self.current_cell = ""
        self.cell_rs = 1
        self.cell_cs = 1
        self.table_classes = []

    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if tag == 'table':
            cls = d.get('class','')
            if 'wikitable' in cls and self.in_wikitable == 0:
                self.in_wikitable = 1
                self.current_table_raw = []
                self.table_classes.append(cls)
            elif self.in_wikitable > 0:
                self.in_wikitable += 1
        elif self.in_wikitable == 1:
            if tag == 'tr':
                self.in_row = True
                self.current_row = []
            elif tag in ('td','th') and self.in_row:
                self.in_cell = True
                self.current_cell = ""
                self.cell_rs = int(d.get('rowspan','1'))
                self.cell_cs = int(d.get('colspan','1'))
            elif tag == 'br' and self.in_cell:
                self.current_cell += "\n"

    def handle_endtag(self, tag):
        if tag == 'table':
            if self.in_wikitable == 1:
                self.tables.append(self.current_table_raw)
                self.in_wikitable = 0
            elif self.in_wikitable > 1:
                self.in_wikitable -= 1
        elif self.in_wikitable == 1:
            if tag == 'tr' and self.in_row:
                self.current_table_raw.append(self.current_row)
                self.in_row = False
            elif tag in ('td','th') and self.in_cell:
                self.current_row.append((self.current_cell.strip(), self.cell_rs, self.cell_cs))
                self.in_cell = False

    def handle_data(self, data):
        if self.in_cell:
            self.current_cell += data

def expand_spans(raw_table):
    """Expand rowspans and colspans into a regular grid"""
    if not raw_table:
        return []
    # Figure out max cols
    max_cols = 0
    for row in raw_table:
        c = sum(cs for _,_,cs in row)
        if c > max_cols:
            max_cols = c

    grid = []
    pending = {}  # (row_idx, col_idx) -> text for future rows due to rowspan

    for ri, row in enumerate(raw_table):
        grid_row = [''] * max_cols
        ci = 0  # position in grid
        raw_ci = 0  # position in raw row

        while ci < max_cols:
            # Check if there's a pending rowspan value
            if (ri, ci) in pending:
                grid_row[ci] = pending[(ri, ci)]
                del pending[(ri, ci)]
                ci += 1
                continue

            if raw_ci >= len(row):
                ci += 1
                continue

            text, rs, cs = row[raw_ci]
            raw_ci += 1

            # Fill colspan
            for c in range(cs):
                if ci + c < max_cols:
                    grid_row[ci + c] = text

            # Fill rowspan for future rows
            if rs > 1:
                for r in range(1, rs):
                    for c in range(cs):
                        pending[(ri + r, ci + c)] = text

            ci += cs

        grid.append(grid_row)

    return grid

# Process Fearless Tour
content = fetch_wiki("https://en.wikipedia.org/wiki/Fearless_Tour")
parser = WikiTableParser()
parser.feed(content)

all_shows = []

for table in parser.tables:
    grid = expand_spans(table)
    if not grid:
        continue
    header = grid[0]
    # Look for Date column
    date_col = -1
    city_col = -1
    country_col = -1
    venue_col = -1
    for j, h in enumerate(header):
        hl = h.lower()
        if 'date' in hl:
            date_col = j
            # Extract year from header like "Date (2010)"
            ym = re.search(r'\((\d{4})\)', h)
            year = ym.group(1) if ym else ""
        elif 'city' in hl:
            city_col = j
        elif 'country' in hl:
            country_col = j
        elif 'venue' in hl:
            venue_col = j

    if date_col == -1:
        continue

    for row in grid[1:]:
        if date_col < len(row):
            date_str = row[date_col].strip()
            city = row[city_col].strip() if city_col < len(row) else ""
            country = row[country_col].strip() if country_col < len(row) else ""
            venue = row[venue_col].strip() if venue_col < len(row) else ""
            if date_str and not date_str.startswith('Total'):
                all_shows.append({
                    'date': date_str,
                    'year': year,
                    'city': city,
                    'country': country,
                    'venue': venue,
                    'tour': 'Fearless Tour'
                })

print(f"Total Fearless Tour shows parsed: {len(all_shows)}")
for s in all_shows[:5]:
    print(s)
print("...")
for s in all_shows[-5:]:
    print(s)

# Save intermediate
with open('/tmp/fearless_shows.json', 'w') as f:
    json.dump(all_shows, f)
