import subprocess, re, json, html as htmlmod

def fetch_wiki(url):
    result = subprocess.run(['curl', '-s', '-L', '-H', 
        'User-Agent: Mozilla/5.0 (X11; Linux x86_64; rv:109.0) Gecko/20100101 Firefox/115.0',
        '-H', 'Accept: text/html', url], capture_output=True, text=True, timeout=30)
    return result.stdout

def parse_wikitables(html_content):
    tables = re.findall(r'<table[^>]*class="[^"]*wikitable[^"]*"[^>]*>(.*?)</table>', html_content, re.DOTALL)
    result = []

    for table_html in tables:
        rows_html = re.findall(r'<tr[^>]*>(.*?)</tr>', table_html, re.DOTALL)

        raw_rows = []
        for row_html in rows_html:
            cells = []
            for m in re.finditer(r'<(t[hd])([^>]*)>(.*?)</\1>', row_html, re.DOTALL):
                tag, attrs, content = m.groups()
                text = re.sub(r'<[^>]+>', ' ', content).strip()
                text = re.sub(r'\s+', ' ', text)
                text = htmlmod.unescape(text)
                rs = int(re.search(r'rowspan="(\d+)"', attrs).group(1)) if re.search(r'rowspan="(\d+)"', attrs) else 1
                cs = int(re.search(r'colspan="(\d+)"', attrs).group(1)) if re.search(r'colspan="(\d+)"', attrs) else 1
                cells.append((text, rs, cs))
            raw_rows.append(cells)

        if not raw_rows:
            continue

        ncols = sum(cs for _, _, cs in raw_rows[0])
        nrows = len(raw_rows)

        grid = [[None]*ncols for _ in range(nrows)]

        for ri, raw_cells in enumerate(raw_rows):
            ci = 0
            raw_idx = 0
            while ci < ncols and raw_idx < len(raw_cells):
                while ci < ncols and grid[ri][ci] is not None:
                    ci += 1
                if ci >= ncols:
                    break
                text, rs, cs = raw_cells[raw_idx]
                raw_idx += 1
                for dr in range(rs):
                    for dc in range(cs):
                        r, c = ri + dr, ci + dc
                        if r < nrows and c < ncols:
                            grid[r][c] = text
                ci += cs

        for ri in range(nrows):
            for ci in range(ncols):
                if grid[ri][ci] is None:
                    grid[ri][ci] = ''

        result.append(grid)

    return result

content = fetch_wiki("https://en.wikipedia.org/wiki/The_Red_Tour")
tables = parse_wikitables(content)

# Table 1 (2013 dates) 
t = tables[1]
# Count data rows excluding Total
count = 0
for row in t[1:]:
    date = row[0].strip()
    if date and 'total' not in date.lower():
        count += 1
    else:
        print(f"Skipping: {row[:4]}")
print(f"Table 1 (2013) data rows: {count}")

# Table 2 (2014 dates)
t = tables[2]
count2 = 0
for row in t[1:]:
    date = row[0].strip()
    if date and 'total' not in date.lower():
        count2 += 1
    else:
        print(f"Skipping: {row[:4]}")
print(f"Table 2 (2014) data rows: {count2}")

print(f"Red Tour total: {count + count2}")

# Also check the Singapore June 9 show - was Bangkok replaced with extra Singapore?
for row in t[1:]:
    if 'Singapore' in str(row) or 'June 9' in str(row):
        print(f"Found: {row[:5]}")
